CREATE TABLE "public"."clients" (
  "id"                 bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "full_name"          text                     NOT NULL,
  "phone"              text,
  "address"            text,
  "budget"             numeric                  NOT NULL DEFAULT 0,
  "deadline"           date,
  "status"             text                     NOT NULL DEFAULT 'new'::text,
  "notes"              text,
  "calc_materials"     jsonb                    NOT NULL DEFAULT '[]'::jsonb,
  "calc_services"      jsonb                    NOT NULL DEFAULT '[]'::jsonb,
  "calc_expenses"      jsonb                    NOT NULL DEFAULT '[]'::jsonb,
  "tasks"              jsonb                    NOT NULL DEFAULT '[]'::jsonb,
  "production_steps"   jsonb                    NOT NULL DEFAULT '{}'::jsonb,
  "created_at"         timestamp with time zone NOT NULL DEFAULT now(),
  "assigned_designer"  uuid,
  "assigned_installer" uuid,
  "updated_by"         uuid,
  "updated_at"         timestamp with time zone DEFAULT now(),
  "portal_token"       uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "budget_coefficient" numeric                  DEFAULT 2.0,
  "cover_url"          text,
  "client_name"        text                     DEFAULT ''::text,
  "project_name"       text                     DEFAULT ''::text,
  "project_scope"      text                     NOT NULL DEFAULT 'firma'::text,
  "important_points"   jsonb                    NOT NULL DEFAULT '[]'::jsonb,
  CONSTRAINT "clients_important_points_is_array" CHECK ((jsonb_typeof(important_points) = 'array'::text)),
  CONSTRAINT "clients_pkey" PRIMARY KEY (id),
  CONSTRAINT "clients_portal_token_key" UNIQUE (portal_token),
  CONSTRAINT "clients_project_scope_check" CHECK ((project_scope = ANY (ARRAY['firma'::text, 'personal'::text]))),
  CONSTRAINT "clients_assigned_designer_fkey" FOREIGN KEY (assigned_designer) REFERENCES public.profiles(id),
  CONSTRAINT "clients_assigned_installer_fkey" FOREIGN KEY (assigned_installer) REFERENCES public.profiles(id),
  CONSTRAINT "clients_updated_by_fkey" FOREIGN KEY (updated_by) REFERENCES public.profiles(id)
);

ALTER TABLE "public"."clients"
  ENABLE ROW LEVEL SECURITY;

CREATE TRIGGER trg_clients_audit
  AFTER INSERT OR DELETE OR UPDATE ON public.clients
  FOR EACH ROW
  EXECUTE FUNCTION public.log_client_changes();

CREATE TRIGGER trg_clients_updated_meta
  BEFORE UPDATE ON public.clients
  FOR EACH ROW
  EXECUTE FUNCTION public.set_updated_meta();

CREATE POLICY "clients_delete_owner_only" ON "public"."clients"
  FOR DELETE
  TO PUBLIC
  USING ((public.current_role_name() = 'owner'::text));

CREATE POLICY "clients_insert_owner_assembler" ON "public"."clients"
  FOR INSERT
  TO PUBLIC
  WITH CHECK ((public.current_role_name() = ANY (ARRAY['owner'::text, 'assembler'::text])));

CREATE POLICY "clients_select_by_role" ON "public"."clients"
  FOR SELECT
  TO PUBLIC
  USING
    (((public.current_role_name() = ANY (ARRAY['owner'::text, 'assembler'::text])) OR ((public.current_role_name() = 'designer'::text) AND (assigned_designer = auth.uid())) OR
    ((public.current_role_name() = 'installer'::text) AND (assigned_installer = auth.uid()))));

CREATE POLICY "clients_update_by_role" ON "public"."clients"
  FOR UPDATE
  TO PUBLIC
  USING
    (((public.current_role_name() = ANY (ARRAY['owner'::text, 'assembler'::text])) OR ((public.current_role_name() = 'designer'::text) AND (assigned_designer = auth.uid())) OR
    ((public.current_role_name() = 'installer'::text) AND (assigned_installer = auth.uid()))));

REVOKE ALL ON SEQUENCE "public"."clients_id_seq" FROM "anon";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."clients_id_seq" TO "anon";

REVOKE ALL ON SEQUENCE "public"."clients_id_seq" FROM "authenticated";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."clients_id_seq" TO "authenticated";

REVOKE ALL ON SEQUENCE "public"."clients_id_seq" FROM "postgres";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."clients_id_seq" TO "postgres";

REVOKE ALL ON SEQUENCE "public"."clients_id_seq" FROM "service_role";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."clients_id_seq" TO "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."clients" TO "authenticated";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."clients" TO "service_role";

COMMENT ON COLUMN "public"."clients"."cover_url" IS 'URL обложки проекта — выбирается из project_files через звёздочку в FilesTab';

REVOKE ALL ON TABLE "public"."clients" FROM "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."clients" TO "postgres";

REVOKE ALL ON TABLE "public"."clients" FROM "anon";
